<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Heat Map | SignalGrid</title>@vite('resources/js/app.js')</head><body class="domain-body">@include('partials.app-navigation')<main id="main-content" class="heatmap-shell"><header class="domain-header"><div><span class="eyebrow">RF ANALYTICS</span><h1>{{ $survey->name }} heat map</h1><p>{{ $survey->floor->building->name }} · {{ $survey->floor->name }}</p></div><a class="secondary" href="{{ route('surveys.show',$survey) }}">Survey workspace</a></header><div class="heatmap-layout"><aside class="panel heatmap-controls"><h3>Generation settings</h3><label>Grid resolution<select id="gridSize"><option value="60,45">Standard · 60 × 45</option><option value="100,75">Detailed · 100 × 75</option><option value="160,120">High · 160 × 120</option></select></label><label>IDW power<input id="idwPower" type="number" value="2" min="1" max="5" step="0.1"></label><label>Coverage threshold<input id="weakThreshold" type="number" value="-75" min="-120" max="0"></label><label>Maximum estimate distance<input id="maxDistance" type="number" value="0.30" min="0.02" max="1" step="0.01"></label><small>0.30 means 30 percent of the longer side. On a calibrated plan this is a distance in metres.</small>@if($survey->floorPlan)<button type="button" class="primary full" id="generateHeatmap">Generate heat map</button>@else<p>Add a floor plan before generating a heat map.</p>@endif<p id="heatmapMessage"></p><hr><div class="rssi-legend-card"><h4>RSSI legend</h4><div class="rssi-ramp"></div><div><span>≤ -75<br><small>Weak</small></span><span>-74 to -67<br><small>Fair</small></span><span>-66 to -60<br><small>Good</small></span><span>≥ -59<br><small>Strong</small></span></div></div></aside><section class="panel heatmap-stage">@if($survey->floorPlan)<div id="heatmapCanvas" class="heatmap-canvas"><img src="{{ route('floor-plans.file',$survey->floorPlan) }}" alt="Floor plan"><canvas id="heatmapOverlay"></canvas>@foreach($survey->points as $point)@if($point->x_normalized !== null && $point->y_normalized !== null)<i class="heat-source {{ $point->source_type }}" style="left:{{ $point->x_normalized*100 }}%;top:{{ $point->y_normalized*100 }}%"></i>@endif
@endforeach</div>@else<div class="domain-empty"><h2>No floor plan</h2><p>Readings can stay on this survey. Add a floor plan before generating a heat map.</p><a class="secondary" href="{{ route('floor-plans.workspace', $survey->floor) }}">Add a floor plan</a></div>@endif</section><aside class="panel heatmap-summary"><h3>Latest result</h3>@php($latestHeatmap = $runs->first())<div><span>Good-signal coverage</span><b id="coverageValue">{{ $latestHeatmap ? number_format((float) $latestHeatmap->coverage_percent, 1).'%' : '—' }}</b></div><div><span>Estimated coverage</span><b id="estimatedArea">{{ $latestHeatmap && $latestHeatmap->estimated_area_percent !== null ? number_format((float) $latestHeatmap->estimated_area_percent, 1).'%' : '—' }}</b></div><div><span>Unmeasured area</span><b id="unmeasuredArea">{{ $latestHeatmap && data_get($latestHeatmap->parameters, 'unmeasured_area_percent') !== null ? number_format((float) data_get($latestHeatmap->parameters, 'unmeasured_area_percent'), 1).'%' : '—' }}</b></div><div><span>Source points</span><b id="sourceCount">{{ optional($runs->first())->source_point_count ?? '—' }}</b></div><div><span>Algorithm</span><b id="algorithmVersion">IDW v{{ optional($runs->first())->algorithm_version ?? '1.1' }}</b></div><p>Coloured cells are estimates. Unmeasured area is not counted as good coverage. Weak is at or below -75 dBm, fair is -74 to -67, good is -66 to -60, and strong is at or above -59.</p><ul class="source-legend"><li><i class="measured"></i> Measured</li><li><i class="imported"></i> Imported</li><li><i class="simulated"></i> Simulated, excluded from scores</li></ul><p id="distanceNote" class="quiet-note">Transparent regions do not have enough nearby measurements.</p></aside></div></main>@php($heatmapGenerateUrl = route('heatmaps.store', $survey))@php($heatmapConfig = ['surveyId' => $survey->id, 'generateUrl' => $heatmapGenerateUrl, 'csrf' => csrf_token(), 'latest' => $runs->first()])<script>window.heatmapConfig=@json($heatmapConfig);</script></body></html>